// Generated by Cypress Author on 2026-11-26.
// Décrire les scénarios du panier Swag Labs.
describe('Swag Labs cart', () => {
    // Se connecter avant le test avec la commande partagée.
    beforeEach(() => {
        // Ouvrir une session utilisateur standard sur l'inventaire.
        cy.login();
    });

    // Fermer la session après le test avec la commande partagée.
    afterEach(() => {
        // Déconnecter l'utilisateur après les vérifications.
        cy.logout();
    });

    // Déclarer le scénario d'ajout de plusieurs produits à compléter.
    it('ajoute plusieurs produits au panier', () => {
        // Ajouter produit N° 1 depuis la page Inventory
        cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
        // Vérifier que le bouton du produit devient Remove
        cy.get('[data-test="remove-sauce-labs-backpack"]').should('have.text', 'Remove');

        // Ajouter produit N° 2 depuis la page Inventory
        cy.get('[data-test="add-to-cart-sauce-labs-fleece-jacket"]').click();
        cy.get('[data-test="remove-sauce-labs-fleece-jacket"]').should('have.text', 'Remove');

        // Ajouter produit N° 3 depuis la page Inventory
        cy.get('[data-test="add-to-cart-test.allthethings()-t-shirt-(red)"]').click();
        cy.get('[data-test="remove-test.allthethings()-t-shirt-(red)"]').should('have.text', 'Remove');

        // Vérifier que le badge du panier affiche 3 produits
        cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '3')
    });
});
